head.script:
	scwin.fireEvent = false;

	scwin.dataMap1_onmodelchange = function(info) {
		var key = info.key;
		var oldValue = info.oldValue;			
		var newValue = info.newValue;


		if(scwin.fireEvent) return;
		scwin.fireEvent = true;

		var cnt = dataMap1.get( "CNT" );

		if(key == "CODE_AC"){
			if(cnt == 1){
				dataMap1.set( "CODE_AC" , "2" );
			}
		};

		if(key == "CODE_S"){
			if(cnt == 1){
				dataMap1.set( "CODE_S" , "2" );
			}
		};

		scwin.fireEvent = false;
	};

scwin.dataMap1_onbeforemodelchange = function(info) {
    //debugger;
		if (info.newValue == "1") {
            //console.log("newValue  == " + info.newValue);
            //console.log("oldValue  == " + info.oldValue);
			return false;
		} else {
			return true;
		}

};


	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('asb_label').innerText == '전체';
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('asb_button').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('asb_itemTable_1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
